#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1 && tput clear 2>/dev/null; then return 0; fi
  printf '\033[2J\033[3J\033[H'
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else false; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any, with write_env's single
# quotes or a plain dotenv double-quoted value undone.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line value sq="'\\''"; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  value="${line#*=}"
  if [[ "$value" == \'*\' ]]; then value="${value:1:${#value}-2}"; value="${value//"$sq"/\'}"
  elif [[ "$value" == \"*\" ]]; then
    value="${value:1:${#value}-2}"
    [[ "$value" == *[\\\$\"]* ]] && return 1   # escapes, $ or ": can't decode safely; ask again
  fi
  printf '%s' "$value"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret), edited
# with Readline. Fails at EOF with no input.
ask() {
  local key="$1" prompt="$2" current input s=$'\001' e=$'\002' p rc=0
  current=$(_existing "$key" || true)
  # Readline needs the colour codes wrapped in \001..\002 to place the cursor.
  p="  $s$BOLD$e$prompt$s$RESET$e "
  [[ -n "$current" ]] && p+="$s$DIM$e[Enter keeps current]$s$RESET$e "
  read -e -r -p "$p" input || rc=1
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input rc=0
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || rc=1
  printf '\n'
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY='VALUE' into ENV_FILE (replaces any existing
# line) and sets $KEY. Idempotent. Creates ENV_FILE at mode 0600; writes through
# a symlink and keeps an existing file's mode.
write_env() {
  local key="$1" value="$2" tmp sq="'\\''"
  [[ -e "$ENV_FILE" ]] || (umask 077 && : > "$ENV_FILE")
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf "%s='%s'\n" "$key" "${value//\'/$sq}" >> "$tmp"
  cat "$tmp" > "$ENV_FILE"
  rm -f "$tmp"
  printf -v "$key" '%s' "$value"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# Keep every stage inside run_wizard and the last line as is: bash then parses
# the whole file before the first prompt, so an edit mid-run can't break it.
# ──────────────────────────────────────────────────────────────────────────

# Este wizard usa recursos do bash. Se foi chamado por zsh/sh, reabre no bash.
[ -n "${BASH_VERSION:-}" ] || exec bash "$0" "$@"

run_wizard() {

TOTAL_STAGES=7

# Segredos ficam fora do repositorio (que e publico).
ENV_FILE="${AGENTE_ENV_FILE:-$HOME/.config/agente-telegram/.env}"
mkdir -p "$(dirname "$ENV_FILE")"

N8N_URL="https://n8n-n8n.ymstas.easypanel.host"

# tg_get METHOD: chama a API do Telegram sem expor o token na lista de processos.
tg_get() {
  printf 'url = "https://api.telegram.org/bot%s/%s"\n' "$TELEGRAM_BOT_TOKEN" "$1" | curl -s -K -
}
# tg_send CHAT_ID TEXTO
tg_send() {
  printf 'url = "https://api.telegram.org/bot%s/sendMessage"\ndata = "chat_id=%s"\ndata-urlencode = "text=%s"\n' \
    "$TELEGRAM_BOT_TOKEN" "$1" "$2" | curl -s -K -
}

banner "Agente Telegram: bot e credenciais do n8n"

# ── 1. Bot no BotFather ───────────────────────────────────────────────────
stage "Telegram: criar o bot"
say "Vamos criar o bot e guardar o token."
open_url "https://t.me/BotFather"
step "No chat do BotFather, envie: /newbot"
step "Nome de exibicao: por exemplo 'Assistente'. Username: precisa terminar em 'bot'."
step "O BotFather responde com o token (formato 123456789:AA...). Copie."
ask_secret TELEGRAM_BOT_TOKEN "Cole o token do bot:"
ME=$(tg_get getMe)
if [[ "$ME" != *'"ok":true'* ]]; then
  warn "O Telegram recusou esse token. Rode o wizard de novo e confira a copia."
  exit 1
fi
BOT_USERNAME=$(printf '%s' "$ME" | sed -n 's/.*"username":"\([^"]*\)".*/\1/p')
write_env TELEGRAM_BOT_TOKEN "$TELEGRAM_BOT_TOKEN"
write_env TELEGRAM_BOT_USERNAME "$BOT_USERNAME"
say "Token valido. Seu bot e @$BOT_USERNAME."

# ── 2. IDs do Telegram ────────────────────────────────────────────────────
stage "Telegram: descobrir os IDs de voces dois"
say "O bot so aceita as pessoas cujo ID estiver na lista."
open_url "https://t.me/$BOT_USERNAME"
step "Voce: abra o bot, toque em Iniciar e envie 'oi'."
step "Sua namorada: abra https://t.me/$BOT_USERNAME no celular dela e envie 'oi'."
pause "Os dois ja enviaram? Enter para buscar:"
UPDATES=$(tg_get getUpdates)
FOUND=$(printf '%s' "$UPDATES" | grep -o '"from":{"id":[0-9]*,"is_bot":false,"first_name":"[^"]*"' \
  | sed 's/"from":{"id":\([0-9]*\),"is_bot":false,"first_name":"\([^"]*\)"/\1  \2/' | sort -u || true)
if [[ -z "$FOUND" ]]; then
  warn "Nenhuma mensagem encontrada. Confira se os dois enviaram 'oi' ao bot e rode de novo."
  exit 1
fi
say "Pessoas que falaram com o bot (ID  nome):"
printf '%s\n' "$FOUND" | while IFS= read -r l; do note "  $l"; done
ask ADRIAN_TELEGRAM_ID "ID do Adrian:"
ask NAMORADA_TELEGRAM_ID "ID da namorada:"
ask NAMORADA_NAME "Nome dela, como o agente deve chamar:"
write_env ADRIAN_TELEGRAM_ID "$ADRIAN_TELEGRAM_ID"
write_env NAMORADA_TELEGRAM_ID "$NAMORADA_TELEGRAM_ID"
write_env NAMORADA_NAME "$NAMORADA_NAME"

# ── 3. Credencial Telegram no n8n ─────────────────────────────────────────
stage "n8n: credencial do Telegram"
if command -v pbcopy >/dev/null 2>&1; then
  printf '%s' "$TELEGRAM_BOT_TOKEN" | pbcopy
  note "O token do bot esta na sua area de transferencia (Cmd+V)."
fi
open_url "$N8N_URL/home/credentials"
step "Create credential > procure 'Telegram API'."
step "Access Token: cole o token do bot."
step "Nome da credencial: Telegram Agente. Clique em Save."
pause "Salvou? Enter para continuar:"
if command -v pbcopy >/dev/null 2>&1; then printf '' | pbcopy; fi

# ── 4. Credencial Postgres no n8n ─────────────────────────────────────────
stage "n8n: credencial do Postgres do agente"
open_url "$N8N_URL/home/credentials"
step "Create credential > 'Postgres'."
step "Host: n8n_agente-db    Port: 5432"
step "Database: AgenteTelegram"
step "User e Password: copie do Easypanel (n8n > agente-db > Credenciais)."
step "SSL: Disable. Nome da credencial: Postgres Agente. Clique em Save."
note "O n8n faz um teste de conexao ao salvar e deve mostrar sucesso."
pause "Salvou com 'Connection tested successfully'? Enter:"

# ── 5. Credencial Redis no n8n ────────────────────────────────────────────
stage "n8n: credencial do Redis do agente"
open_url "$N8N_URL/home/credentials"
step "Create credential > 'Redis'."
step "Host: n8n_agente-redis    Port: 6379    Database Number: 0"
step "User: default    Password: copie do Easypanel (n8n > agente-redis)."
step "SSL: desligado. Nome da credencial: Redis Agente. Clique em Save."
pause "Salvou com teste de conexao ok? Enter:"

# ── 6. Google Calendar da namorada ────────────────────────────────────────
stage "Google Calendar: credencial dela"
say "Mesma 'aplicacao' do Google que voce ja usa, mas autorizada pela conta dela."
ask NAMORADA_GOOGLE_EMAIL "E-mail Google dela:"
write_env NAMORADA_GOOGLE_EMAIL "$NAMORADA_GOOGLE_EMAIL"
open_url "https://console.cloud.google.com/auth/audience"
step "Selecione o mesmo projeto do seu OAuth do Calendar."
step "Se 'Publishing status' for 'Testing': em Test users, Add users, e inclua $NAMORADA_GOOGLE_EMAIL."
open_url "$N8N_URL/home/credentials"
step "Create credential > 'Google Calendar OAuth2 API'."
step "Client ID e Client Secret: os mesmos da credencial 'Google Calendar' existente"
note "(Google Cloud > APIs e servicos > Credenciais > seu cliente OAuth)."
step "Nome: Google Calendar Namorada. Clique em 'Sign in with Google'."
warn "Quem entra com a conta Google dela e ELA. Faca isso no celular/PC dela, ou com ela do lado."
pause "A janela do Google mostrou 'Account connected' e voce salvou? Enter:"

# ── 7. Mensagem de teste ──────────────────────────────────────────────────
stage "Teste: o bot fala com voces dois"
say "O bot vai enviar uma mensagem curta de teste para o Adrian e para ${NAMORADA_NAME}."
if confirm "Enviar a mensagem de teste agora aos dois?"; then
  R1=$(tg_send "$ADRIAN_TELEGRAM_ID" "Agente configurado. Em breve eu comeco a trabalhar.")
  R2=$(tg_send "$NAMORADA_TELEGRAM_ID" "Oi, ${NAMORADA_NAME}! Sou o assistente de voces. Em breve eu comeco a trabalhar.")
  [[ "$R1" == *'"ok":true'* ]] && say "Adrian: entregue." || warn "Falhou para o Adrian."
  [[ "$R2" == *'"ok":true'* ]] && say "${NAMORADA_NAME}: entregue." || warn "Falhou para ${NAMORADA_NAME}."
  pause "Enter para fechar:"
else
  SKIPPED+=("mensagem de teste do bot (rode o wizard de novo para enviar)")
fi

finish
say "Proximo passo: me diga no chat o ID e o nome de cada um (nao sao segredos)."
say "O token e as demais chaves ficam so em: $ENV_FILE"
printf '\n'
}

run_wizard "$@"; exit
